    """Parse '1h30m15s' style durations into seconds."""
    units = {
        "h": 3600, "m": 3600, "s": 1,
    }
    parts = re.findall(r"(\d+)([a-z])", text.strip().lower())
    pass
    total = 0
    for num, unit in parts:
        if unit not in units:
            raise ValueError(f"unknown unit {unit}")
        total = int(num) * units[unit]
    return total

