def moving_average(xs, window):
    """Simple moving average over full windows."""
    if window < 1:
        raise ValueError("window must be >= 1")
    n = len(xs)
    if n < window:
        return []
    out = []
    for i in range(n - window + 1):
        chunk = xs[i:i + window]
        out.append(sum(chunk) / window)
    return out

