def split_bill(total_cents, n):
    """Split total_cents cents among n people, shares differ by at most 1 cent,
    larger shares first, and raise ValueError for n <= 0."""
    if n <= 0:
        raise ValueError("n must be a positive integer")
    base = total_cents // n
    remainder = total_cents % n
    # First `remainder` people get an extra cent
    return [base + 1] * remainder + [base] * (n - remainder)

