def compare_versions(a, b):
    if a == b:
        return 0
    return 1 if a > b else -1

def compare_versions(a, b):
    def split_version(v):
        if '-' in v:
            base, pre = v.split('-', 1)
            return base, pre
        return v, None

    base_a, pre_a = split_version(a)
    base_b, pre_b = split_version(b)

    def num_parts(s):
        return [int(part) for part in s.split('.')]

    parts_a = num_parts(base_a)
    parts_b = num_parts(base_b)

    max_len = max(len(parts_a), len(parts_b))
    for i in range(max_len):
        pa = parts_a[i] if i < len(parts_a) else 0
        pb = parts_b[i] if i < len(parts_b) else 0
        if pa != pb:
            return 1 if pa > pb else -1

    # Numeric parts are equal; handle pre‑release suffixes
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1
