import datetime


def business_days(start, end):
    """Return the number of weekdays (Mon‑Fri) from start (inclusive) to end (exclusive)."""
    if not isinstance(start, datetime.date) or not isinstance(end, datetime.date):
        raise TypeError("Both start and end must be datetime.date instances")

    if end == start:
        return 0
    if end > start:
        delta = end - start
        return sum(1 for i in range(delta.days) if (start + datetime.timedelta(days=i)).weekday() < 5)
    else:
        return -business_days(end, start)

