import numpy as np

def percentile(xs, p):
    """Return the p‑th percentile of xs using linear interpolation (NumPy default)."""
    if not xs:
        raise ValueError("xs must not be empty")
    if not (0 <= p <= 100):
        raise ValueError("p must be in [0, 100]")
    # Work on a sorted copy to avoid mutating the original list
    sorted_xs = sorted(xs)
    # Convert to a NumPy array for accurate linear interpolation
    arr = np.asarray(sorted_xs)
    return np.percentile(arr, p, method='linear')

def percentile(xs, p):
    """Return the p‑th percentile of xs using NumPy's linear interpolation."""
    if not xs:
        raise ValueError("Empty input sequence")
    if not (0 <= p <= 100):
        raise ValueError("p must be in [0, 100]")
    xs_sorted = sorted(xs)          # work on a sorted copy, no mutation
    n = len(xs_sorted)
    if n == 1:
        return xs_sorted[0]
    # Compute the exact (continuous) index corresponding to p
    pos = (p / 100) * (n - 1)       # position in [0, n‑1]
    lower_idx = int(pos)            # floor
    upper_idx = lower_idx + 1
    weight = pos - lower_idx        # fractional part
    if weight == 0:
        return xs_sorted[lower_idx]
    # Linear interpolation between the two surrounding values
    return xs_sorted[lower_idx] + weight * (xs_sorted[upper_idx] - xs_sorted[lower_idx])

