        if line[i] == '"':
            # Start of a quoted field
            i += 1  # skip opening quote
            field_parts = []
            while i < n:
                if line[i] == '"':
                    # Check for escaped quote ("")
                    if i + 1 < n and line[i + 1] == '"':
                        field_parts.append('"')
                        i += 2  # consume both quotes
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    field_parts.append(line[i])
                    i += 1
            else:
                # Reached end without finding closing quote
                raise ValueError("unmatched quote")
            fields.append(''.join(field_parts))
        else:
            # Unquoted field: read until comma or end
            j = i
            while j < n and line[j] != ',':
                j += 1
            fields.append(line[i:j])
            i = j + 1  # move past the comma (if any)
    return fields

def parse_csv_line(line):
    if line == "":
        return [""]
    fields = []
    field = ""
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped quote
                if i + 1 < n and line[i + 1] == '"':
                    field += '"'
                    i += 1  # skip the next quote
                else:
                    # Closing quote
                    in_quotes = False
            else:
                field += ch
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(field)
                field = ""
            else:
                field += ch
        i += 1
    if in_quotes:
        raise ValueError("Unmatched quote")
    fields.append(field)
    return fields

def parse_csv_line(line):
